using System.Text.RegularExpressions;

namespace PaRuX.Server;

/// <summary>Typed refusal for a managed Python install that is not hash-locked (SEC-F02).</summary>
internal sealed class ManagedPipRefusalException(string code, string message) : InvalidOperationException(message)
{
    internal string Code { get; } = code;
}

/// <summary>
/// Hash-locked requirement sets shipped next to the app (<c>managed-locks/*.lock.txt</c>, generated by
/// <c>tools/managed-locks/generate.ps1</c>). Every entry is <c>name==version</c> (or <c>name @ https-url</c>) with at
/// least one <c>--hash=sha256:</c>; any other option line (index, find-links, editable, nested -r) is refused.
/// </summary>
internal static partial class ManagedRequirementLocks
{
    /// <summary>The CPython minor the shipped locks were resolved for (see tools/managed-locks/generate.ps1).</summary>
    internal const string LockPythonMinor = "3.11";
    internal const string MissingCode = "lock_missing";
    internal const string InvalidCode = "lock_invalid";

    /// <summary>Directory holding the shipped lock files. Tests may point it at a fixture folder.</summary>
    internal static string Directory { get; set; } = Path.Combine(AppContext.BaseDirectory, "managed-locks");

    internal static string PathFor(string setId) => Path.Combine(Directory, setId + ".lock.txt");

    /// <summary>
    /// Hashed pins for the build-system requirements of source distributions (setuptools, wheel, numpy, cython). uv fetches those
    /// outside <c>--require-hashes</c> unless they are passed as <c>--build-constraints</c>; a requirement not listed there is
    /// still resolved unhashed (documented residual in docs/SECURITY_REVIEW.md).
    /// </summary>
    internal const string BuildConstraintsSetId = "build-constraints";
    internal static string BuildConstraintsPath => PathFor(BuildConstraintsSetId);

    [GeneratedRegex(@"^[A-Za-z0-9][A-Za-z0-9._-]*(\[[A-Za-z0-9,._-]+\])?==[A-Za-z0-9][A-Za-z0-9._+!-]*$")]
    private static partial Regex PinPattern();
    [GeneratedRegex(@"^[A-Za-z0-9][A-Za-z0-9._-]*@https://\S+$")]
    private static partial Regex UrlPinPattern();
    [GeneratedRegex(@"^--hash=sha256:[0-9a-f]{64}$")]
    private static partial Regex HashPattern();

    /// <summary>Returns the number of locked requirements or throws a typed refusal.</summary>
    internal static int Validate(string lockPath)
    {
        if (string.IsNullOrWhiteSpace(lockPath) || !File.Exists(lockPath))
            throw new ManagedPipRefusalException(MissingCode,
                "The dependency lock '" + Path.GetFileName(lockPath) + "' is missing; PaRuX will not install unpinned packages.");

        string text = File.ReadAllText(lockPath).Replace("\r\n", "\n").Replace("\\\n", " ");
        int count = 0;
        foreach (string raw in text.Split('\n'))
        {
            string line = raw.Trim();
            if (line.Length == 0 || line.StartsWith('#')) continue;
            string[] parts = line.Split(' ', StringSplitOptions.RemoveEmptyEntries);
            // Everything after the requirement must be a hash; a trailing "# via" comment is dropped first.
            int comment = Array.FindIndex(parts, p => p.StartsWith('#'));
            if (comment >= 0) parts = parts[..comment];
            string requirement = parts[0];
            string[] rest = parts[1..];
            if (rest.Length > 0 && rest[0] == "@" && rest.Length > 1)
            {
                requirement = parts[0] + "@" + rest[1];
                rest = rest[2..];
            }
            requirement = requirement.Split(';')[0];
            bool pinned = PinPattern().IsMatch(requirement) || UrlPinPattern().IsMatch(requirement);
            if (!pinned || rest.Length == 0 || !rest.All(p => HashPattern().IsMatch(p)))
                throw new ManagedPipRefusalException(InvalidCode,
                    "Dependency lock '" + Path.GetFileName(lockPath) + "' has an unpinned, unhashed or option line: " + parts[0]);
            count++;
        }
        if (count == 0)
            throw new ManagedPipRefusalException(InvalidCode, "Dependency lock '" + Path.GetFileName(lockPath) + "' contains no requirements.");
        return count;
    }

    /// <summary>The pip arguments for a shipped, validated lock set.</summary>
    internal static IReadOnlyList<string> ArgumentsFor(string setId)
    {
        string path = PathFor(setId);
        Validate(path);
        string buildConstraints = BuildConstraintsPath;
        Validate(buildConstraints);
        return new[] { "--require-hashes", "--no-deps", "--build-constraints", buildConstraints, "-r", path };
    }

    /// <summary>The hashed torch closure for a known PyTorch index, or null for an unknown index.</summary>
    internal static string? TorchLockFor(string indexUrl)
    {
        string? set = string.Equals(indexUrl, ExLlamaV3BuildCatalog.TorchIndexUrl, StringComparison.OrdinalIgnoreCase) ? "torch-cu128"
            : string.Equals(indexUrl, TorchInstallChannelPolicy.CpuTorchIndexUrl, StringComparison.OrdinalIgnoreCase) ? "torch-cpu"
            : null;
        return set == null ? null : PathFor(set);
    }
}

/// <summary>
/// Gate in front of every managed <c>uv pip install</c>: an install must be hash-locked, a known PyTorch pin that
/// resolves to a hashed lock, or belong to an explicitly registered unlocked set. Anything else is refused before a
/// process starts (SEC-F02).
/// </summary>
internal static class ManagedPipInstallPolicy
{
    internal const string UnlockedCode = "unlocked_requirement_set";

    /// <summary>Install sets that cannot be hash-locked yet, with the exact reason. Keep this list shrinking.</summary>
    internal static readonly IReadOnlyDictionary<string, string> UnlockedSets = new Dictionary<string, string>(StringComparer.Ordinal)
    {
        ["exllamav3-wheel"] = "The ExLlamaV3 wheel is SHA-256 verified against its release digest, but its own dependencies resolve unpinned."
    };

    private static bool IsKnownTorchIndex(string url) =>
        string.Equals(url, ExLlamaV3BuildCatalog.TorchIndexUrl, StringComparison.OrdinalIgnoreCase)
        || string.Equals(url, TorchInstallChannelPolicy.CpuTorchIndexUrl, StringComparison.OrdinalIgnoreCase);

    internal static IReadOnlyList<string> Evaluate(IEnumerable<string> arguments, string? unlockedSetId = null)
    {
        List<string> args = arguments.ToList();

        if (args.Contains("--require-hashes", StringComparer.Ordinal))
        {
            // Exactly: --require-hashes --no-deps [--index-url <known PyTorch index>] [--build-constraints <shipped build lock>] -r <validated lock>.
            // Any other flag (--no-verify-hashes, --constraint, --extra-index-url, a second -r, ...) is refused.
            int i = 2;
            bool shape = args.Count >= 4 && args[0] == "--require-hashes" && args[1] == "--no-deps";
            if (shape && i + 1 < args.Count && args[i] == "--index-url")
            {
                shape = IsKnownTorchIndex(args[i + 1]);
                i += 2;
            }
            if (shape && i + 1 < args.Count && args[i] == "--build-constraints")
            {
                shape = string.Equals(args[i + 1], ManagedRequirementLocks.BuildConstraintsPath, StringComparison.OrdinalIgnoreCase);
                if (shape) ManagedRequirementLocks.Validate(args[i + 1]);
                i += 2;
            }
            shape = shape && args.Count == i + 2 && args[i] == "-r" && !args[i + 1].StartsWith('-');
            if (!shape)
                throw new ManagedPipRefusalException(ManagedRequirementLocks.InvalidCode,
                    "A hash-locked install must be exactly: --require-hashes --no-deps [--index-url <PyTorch index>] [--build-constraints <shipped build lock>] -r <lock>.");
            ManagedRequirementLocks.Validate(args[^1]);
            return args;
        }

        // The channel-selected PyTorch pin resolves to the hashed per-channel closure instead of an unpinned fetch.
        if (args.Count == 3 && args[0] == "torch==" + ExLlamaV3BuildCatalog.TorchVersion && args[1] == "--index-url"
            && ManagedRequirementLocks.TorchLockFor(args[2]) is { } torchLock)
        {
            ManagedRequirementLocks.Validate(torchLock);
            return new[] { "--require-hashes", "--no-deps", "--index-url", args[2], "-r", torchLock };
        }

        // The one registered unlocked set is a single, already-verified local wheel file and nothing else.
        if (unlockedSetId == "exllamav3-wheel" && args.Count == 1 && !args[0].StartsWith('-')
            && args[0].EndsWith(".whl", StringComparison.OrdinalIgnoreCase) && Path.IsPathFullyQualified(args[0])
            && File.Exists(args[0]))
            return args;

        throw new ManagedPipRefusalException(UnlockedCode,
            "PaRuX will not install an unpinned Python requirement set in a managed environment (" + string.Join(' ', args.Take(4)) + "...).");
    }
}
